"use client";

import { useEffect, useState } from "react";
import { supabase } from "../../../lib/supabase";

const KITCHEN = "data:image/jpeg;base64,";
const FAMILY = "data:image/jpeg;base64,";
const SERVING = "data:image/jpeg;base64,";
const LOGO = "data:image/jpeg;base64,";

const EN = {
  home: "HOME",
  story: "OUR STORY",
  menu: "MENU",
  catering: "CATERING",
  order: "ORDER ONLINE",
  locations: "LOCATIONS",
  contact: "CONTACT",
  hero1: "MADE WITH PRIDE.",
  hero2: "FLAVOR THAT BRINGS US TOGETHER.",
  body: "Authentic Honduran food made with family recipes, fresh ingredients, and the heart of our people.",
  heritage: "WE ARE HONDURAS\nWE ARE FAMILY",
  v1: "VOTED BEST\nCHICKEN",
  v2: "FRESH\nINGREDIENTS",
  v3: "FAMILY\nRECIPES",
  v4: "PROUDLY\nHONDURAN",
  storyEyebrow: "OUR STORY",
  storyTitle: "From our roots\nto your table",
  storyBody: "Vi Pollos was born from the dream of a Honduran family that arrived with hope and hard work. Today, we continue honoring our traditions with every plate we serve.",
  signature: "With love,\nThe Vi Pollos Family",
  featured: "WHY VI POLLOS",
  d1: "AUTHENTIC\nHONDURAN FLAVOR",
  d2: "MADE FRESH\nEVERY DAY",
  d3: "FAMILY\nRECIPES",
  d4: "WARM\nHOSPITALITY",
  occasion: "FOR EVERY OCCASION",
  cateringTitle: "CATERING &\nFAMILY MEALS",
  cateringBody: "From family gatherings to special events, we bring the flavor of Honduras to your table.",
  event: "PLAN YOUR EVENT",
  quote: "The best grilled chicken I’ve had outside Honduras. It tastes like home, family, and our roots.",
  guest: "HAPPY VI POLLOS GUEST",
  visit: "VISIT US",
  map: "VIEW ON MAP",
  footer: "© 2026 Vi Pollos. All rights reserved."
};

const ES = {
  ...EN,
  home: "INICIO",
  story: "NUESTRA HISTORIA",
  menu: "MENÚ",
  catering: "CATERING",
  order: "ORDENAR",
  locations: "UBICACIONES",
  contact: "CONTACTO",
  hero1: "HECHO CON ORGULLO.",
  hero2: "SABOR QUE NOS UNE.",
  body: "Auténtica comida hondureña hecha con recetas familiares, ingredientes frescos y el corazón de nuestra gente.",
  heritage: "SOMOS HONDURAS\nSOMOS FAMILIA",
  v1: "VOTADO MEJOR\nPOLLO",
  v2: "INGREDIENTES\nFRESCOS",
  v3: "RECETAS DE\nFAMILIA",
  v4: "ORGULLOSAMENTE\nHONDUREÑOS",
  storyEyebrow: "NUESTRA HISTORIA",
  storyTitle: "De nuestras raíces\na tu mesa",
  storyBody: "Vi Pollos nació del sueño de una familia hondureña que llegó con esperanza y trabajo duro. Hoy, seguimos honrando nuestras tradiciones con cada plato que servimos.",
  signature: "Con amor,\nLa Familia Vi Pollos",
  featured: "POR QUÉ VI POLLOS",
  d1: "AUTÉNTICO SABOR\nHONDUREÑO",
  d2: "HECHO FRESCO\nCADA DÍA",
  d3: "RECETAS DE\nFAMILIA",
  d4: "CALIDEZ Y\nHOSPITALIDAD",
  occasion: "PARA CADA OCASIÓN",
  cateringBody: "Desde reuniones familiares hasta eventos especiales, llevamos el sabor de Honduras a tu mesa.",
  event: "ORDENA PARA TU EVENTO",
  quote: "El mejor pollo asado que he probado fuera de Honduras. Sabe a hogar, a familia, a nuestra tierra.",
  guest: "CLIENTE FELIZ",
  visit: "VISÍTANOS",
  map: "VER EN EL MAPA",
  footer: "© 2026 Vi Pollos. Todos los derechos reservados."
};

type Props = {
  restaurantId: string;
  slug: string;
};

type RestaurantData = {
  id: string;
  name: string;
  phone: string | null;
  address_line_1: string | null;
  city: string | null;
  state: string | null;
  zip: string | null;
};

type OrderingData = {
  online_ordering_url: string | null;
  catering_email: string | null;
};

type WebsiteData = {
  about_title: string | null;
  about_body: string | null;
  published: boolean | null;
};

type HoursData = {
  monday: string | null;
  tuesday: string | null;
  wednesday: string | null;
  thursday: string | null;
  friday: string | null;
  saturday: string | null;
  sunday: string | null;
};

export default function ViPollosCustomTheme({ restaurantId, slug }: Props) {
  const [spanish, setSpanish] = useState(false);
  const [restaurant, setRestaurant] = useState<RestaurantData | null>(null);
  const [ordering, setOrdering] = useState<OrderingData | null>(null);
  const [website, setWebsite] = useState<WebsiteData | null>(null);
  const [hours, setHours] = useState<HoursData | null>(null);
  const [loading, setLoading] = useState(true);

  const t = spanish ? ES : EN;

  useEffect(() => {
    async function loadRestaurantOSData() {
      const [restaurantResult, orderingResult, websiteResult, hoursResult] =
        await Promise.all([
          supabase
            .from("restaurants")
            .select("id,name,phone,address_line_1,city,state,zip")
            .eq("id", restaurantId)
            .maybeSingle(),
          supabase
            .from("restaurant_ordering")
            .select("online_ordering_url,catering_email")
            .eq("restaurant_id", restaurantId)
            .maybeSingle(),
          supabase
            .from("restaurant_website_settings")
            .select("about_title,about_body,published")
            .eq("restaurant_id", restaurantId)
            .maybeSingle(),
          supabase
            .from("restaurant_hours")
            .select("monday,tuesday,wednesday,thursday,friday,saturday,sunday")
            .eq("restaurant_id", restaurantId)
            .maybeSingle(),
        ]);

      setRestaurant(restaurantResult.data || null);
      setOrdering(orderingResult.data || null);
      setWebsite(websiteResult.data || null);
      setHours(hoursResult.data || null);
      setLoading(false);
    }

    loadRestaurantOSData();
  }, [restaurantId]);

  const orderUrl =
    ordering?.online_ordering_url ||
    "https://www.doordash.com/store/vi-pollos-clayton-41942251/";

  const cateringHref = ordering?.catering_email
    ? `mailto:${ordering.catering_email}`
    : `mailto:vivianrod86@gmail.com`;

  const addressLine = restaurant?.address_line_1 || "8928 Clayton Blvd";
  const cityStateZip = [
    restaurant?.city || "Clayton",
    restaurant?.state || "NC",
    restaurant?.zip || "27520",
  ]
    .filter(Boolean)
    .join(", ");

  const phone = restaurant?.phone || "9198798000";

  const storyTitle =
    website?.about_title?.trim() ||
    t.storyTitle;

  const storyBody =
    website?.about_body?.trim() ||
    t.storyBody;

  const hoursText =
    hours?.wednesday || hours?.thursday || hours?.friday
      ? [
          hours?.wednesday ? `Wed ${hours.wednesday}` : null,
          hours?.thursday ? `Thu ${hours.thursday}` : null,
          hours?.friday ? `Fri ${hours.friday}` : null,
          hours?.saturday ? `Sat ${hours.saturday}` : null,
          hours?.sunday ? `Sun ${hours.sunday}` : null,
          hours?.monday ? `Mon ${hours.monday}` : null,
          hours?.tuesday ? `Tue ${hours.tuesday}` : null,
        ]
          .filter(Boolean)
          .join("\n")
      : "Wed 9 AM–8 PM\nThu–Sat 9 AM–10 PM\nSun–Tue 9 AM–8 PM";

  if (loading) {
    return (
      <main
        style={{
          minHeight: "100vh",
          display: "grid",
          placeItems: "center",
          background: "#061a31",
          color: "#fff",
          fontFamily: "Arial, Helvetica, sans-serif",
        }}
      >
        Loading Vi Pollos...
      </main>
    );
  }

  return (
    <main className="page">
      <style jsx global>{`
        * { box-sizing: border-box; }
        html, body { margin:0; padding:0; background:#061a31; font-family: Arial, Helvetica, sans-serif; }
        a { color:inherit; text-decoration:none; }
      `}</style>

      <style jsx>{`
        .page { min-height:100vh; background:#061a31; color:#fff; }
        .site { max-width:1440px; margin:0 auto; background:#f2eadc; box-shadow:0 0 70px rgba(0,0,0,.45); }

        .hero { position:relative; height:530px; overflow:hidden; background:#050505; }
        .heroGrid { position:absolute; inset:0; display:grid; grid-template-columns: 34% 33% 33%; }
        .heroLeftBg { background:#050505; }
        .heroImg { width:100%; height:100%; object-fit:cover; }
        .heroShade { position:absolute; inset:0; background:linear-gradient(90deg, rgba(0,0,0,.98) 0 31%, rgba(0,0,0,.60) 43%, rgba(0,0,0,.04) 68%); z-index:1; }
        .nav { position:relative; z-index:5; height:98px; display:flex; align-items:center; padding:0 58px; gap:24px; }
        .logo { width:240px; height:92px; object-fit:contain; object-position:left center; }
        .navLinks { margin-left:auto; display:flex; gap:25px; align-items:center; font-size:12px; font-weight:900; }
        .navLinks a:first-child { color:#d9ad21; border-bottom:2px solid #d9ad21; padding-bottom:9px; }
        .topOrder { padding:14px 24px; background:#075cb3; font-weight:900; }
        .lang { padding:12px 16px; border:1px solid rgba(255,255,255,.4); background:rgba(0,0,0,.45); color:white; border-radius:3px; cursor:pointer; font-weight:800; }

        .heroCopy { position:relative; z-index:3; width:34%; padding:38px 24px 28px 60px; }
        .heroCopy h1 { margin:0; font-family:Impact,Haettenschweiler,"Arial Narrow Bold",sans-serif; font-size:62px; line-height:.94; letter-spacing:1px; font-weight:400; }
        .heroBlue { display:block; color:#0755a6; font-family:Impact,Haettenschweiler,"Arial Narrow Bold",sans-serif; font-style:normal; font-weight:400; font-size:.76em; line-height:.94; margin-top:10px; letter-spacing:1px; }
        .heroCopy p { max-width:440px; font-size:15px; line-height:1.55; margin:20px 0 22px; }
        .heroBtns { display:flex; gap:16px; }
        .btnBlue, .btnOutline { padding:14px 22px; font-weight:900; font-size:13px; }
        .btnBlue { background:#075cb3; }
        .btnOutline { border:1px solid #fff; }
        .heritage { display:inline-flex; white-space:pre-line; margin-top:24px; border:1px solid rgba(255,255,255,.32); padding:8px 14px; font-size:10px; line-height:1.25; font-weight:900; letter-spacing:1px; }

        .values { display:grid; grid-template-columns:repeat(4,1fr); background:#f3eadb; color:#0c2d55; min-height:78px; border-bottom:1px solid #decfb8; }
        .value { display:flex; justify-content:center; align-items:center; gap:14px; padding:14px 18px; border-right:1px solid #d6c7ad; font-size:12px; font-weight:900; white-space:pre-line; line-height:1.2; }
        .value:last-child { border-right:none; }
        .valueIcon { font-size:27px; }

        .middle { display:grid; grid-template-columns: 25% 25% 50%; min-height:390px; }
        .storyText { background:#083765; padding:32px 28px 28px 60px; display:flex; flex-direction:column; justify-content:center; }
        .eyebrow { color:#d6a51f; font-size:11px; font-weight:900; letter-spacing:1.2px; margin-bottom:10px; }
        .storyText h2 { margin:0 0 16px; font-family:Georgia,serif; font-size:34px; line-height:1.05; white-space:pre-line; }
        .storyText p { margin:0 0 16px; font-size:12px; line-height:1.55; color:#edf2f7; }
        .signature { color:#e0a724; font-family:cursive; font-size:20px; line-height:1.05; white-space:pre-line; }
        .familyPhoto { width:100%; height:100%; object-fit:cover; object-position:center; }

        .featured { background:#f3eadb; color:#0b2c52; padding:34px 38px; display:flex; flex-direction:column; justify-content:center; }
        .featured h3 { margin:0 0 28px; text-align:center; font-family:Georgia,serif; letter-spacing:2px; font-size:19px; }
        .dishRow { display:grid; grid-template-columns:repeat(2,1fr); gap:16px; max-width:720px; margin:0 auto; width:100%; }
        .dish { background:#fff8ed; border:1px solid rgba(10,46,84,.10); border-radius:7px; min-height:128px; padding:20px 18px; display:flex; align-items:center; gap:16px; box-shadow:0 5px 15px rgba(0,0,0,.06); }
        .dishIcon { width:52px; height:52px; flex:0 0 52px; border:2px solid #0b4f93; border-radius:50%; display:flex; align-items:center; justify-content:center; font-size:25px; color:#0b4f93; }
        .dish span { display:block; padding:0; text-align:left; white-space:pre-line; font-size:12px; font-weight:900; line-height:1.25; letter-spacing:.2px; }

        .bottom { display:grid; grid-template-columns: 1.05fr 1fr .95fr; min-height:245px; }
        .bottomImg { width:100%; height:100%; object-fit:cover; }
        .caterBox { background:linear-gradient(135deg,#17120f,#241a12); color:white; padding:34px 38px; display:flex; flex-direction:column; justify-content:center; border-top:3px solid #b6841f; }
        .caterBox h3 { margin:0 0 10px; font-family:Georgia,serif; font-size:24px; line-height:1.05; white-space:pre-line; }
        .caterBox p { margin:0 0 14px; font-size:12px; line-height:1.5; }
        .eventBtn { width:max-content; border:1px solid #fff; padding:9px 12px; font-size:10px; font-weight:900; }
        .quoteBox { background:#073664; padding:34px 38px; display:flex; flex-direction:column; align-items:center; justify-content:center; text-align:center; border-top:3px solid #b6841f; }
        .quoteMark { font-size:52px; line-height:.5; color:#d3a126; font-family:Georgia,serif; }
        .quoteBox p { font-family:Georgia,serif; font-size:16px; line-height:1.45; margin:12px auto; max-width:390px; }
        .stars { color:#f6b318; letter-spacing:4px; margin-bottom:8px; }
        .guest { font-size:9px; font-weight:900; letter-spacing:1.7px; }
        .visit { background:#f3eadb; color:#0c2d55; padding:34px 38px; display:flex; flex-direction:column; justify-content:center; border-top:3px solid #b6841f; }
        .visit h3 { margin:0 0 14px; font-family:Georgia,serif; letter-spacing:1px; font-size:20px; }
        .visit p { margin:0 0 7px; font-size:11px; line-height:1.45; }
        .mapBtn { width:max-content; margin-top:7px; padding:10px 14px; background:#082e59; color:#fff; font-size:10px; font-weight:900; }

        .footer { background:#06294d; color:#dbe4ed; text-align:center; padding:13px 20px; font-size:10px; }

        @media(max-width:1050px) {
          .navLinks { display:none; }
          .nav { padding:0 28px; }
          .logo { width:205px; }
          .heroCopy { width:48%; padding-left:34px; }
          .heroGrid { grid-template-columns: 40% 30% 30%; }
          .middle { grid-template-columns:1fr 1fr; }
          .featured { grid-column:1 / -1; }
          .bottom { grid-template-columns:1fr; }
        }
        @media(max-width:700px) {
          .hero { height:auto; min-height:760px; }
          .nav { height:82px; padding:0 16px; gap:10px; }
          .logo { width:150px; height:68px; }
          .topOrder { margin-left:auto; padding:10px 12px; font-size:10px; }
          .lang { padding:9px 10px; font-size:10px; }
          .heroGrid { inset:300px 0 0; grid-template-columns:1fr 1fr; }
          .heroGrid .heroLeftBg { display:none; }
          .heroShade { background:linear-gradient(180deg,#050505 0 41%,rgba(0,0,0,.70) 53%,rgba(0,0,0,.08) 78%); }
          .heroCopy { width:100%; padding:26px 20px 28px; }
          .heroCopy h1 { font-size:46px; max-width:440px; }
          .values { grid-template-columns:1fr 1fr; }
          .value { border-bottom:1px solid #d6c7ad; }
          .middle { grid-template-columns:1fr; }
          .storyText { padding:34px 26px; }
          .familyPhoto { height:350px; }
          .dishRow { grid-template-columns:1fr 1fr; }
          .bottom { grid-template-columns:1fr; }
          .bottomImg { height:250px; }
        }
      `}</style>

      <div className="site">
        {!website?.published && (
          <div
            style={{
              position: "fixed",
              right: 14,
              bottom: 14,
              zIndex: 1000,
              background: "#d9ad21",
              color: "#061a31",
              padding: "8px 11px",
              borderRadius: 4,
              fontSize: 10,
              fontWeight: 900,
              letterSpacing: 1,
              boxShadow: "0 6px 20px rgba(0,0,0,.25)",
            }}
          >
            RESTAURANT OS PREVIEW
          </div>
        )}
        <section className="hero">
          <div className="heroGrid">
            <div className="heroLeftBg" />
            <img className="heroImg" src={KITCHEN} alt="Vi Pollos kitchen" />
            <img className="heroImg" src={SERVING} alt="Vi Pollos serving food" />
          </div>
          <div className="heroShade" />

          <nav className="nav">
            <img src={LOGO} alt="Vi Pollos" className="logo" />
            <div className="navLinks">
              <a href={`/r/${slug}`}>{t.home}</a>
              <a href="#story">{t.story}</a>
              <a href={`/r/${slug}/food-menu`}>{t.menu}</a>
              <a href={cateringHref}>{t.catering}</a>
              <a href={orderUrl} target="_blank" rel="noreferrer">{t.order}</a>
              <a href="#visit">{t.locations}</a>
              <a href="#visit">{t.contact}</a>
            </div>
            <a className="topOrder" href={orderUrl} target="_blank" rel="noreferrer">{t.order}</a>
            <button className="lang" onClick={() => setSpanish(!spanish)}>{spanish ? "🇺🇸 English" : "🇭🇳 Español"}</button>
          </nav>

          <div className="heroCopy">
            <h1>{t.hero1}<span className="heroBlue">{t.hero2}</span></h1>
            <p>{t.body}</p>
            <div className="heroBtns">
              <a className="btnBlue" href={orderUrl} target="_blank" rel="noreferrer">{t.order} →</a>
              <a className="btnOutline" href={`/r/${slug}/food-menu`}>{t.menu}</a>
            </div>
            <div className="heritage">🇭🇳 {t.heritage}</div>
          </div>
        </section>

        <section className="values">
          <div className="value"><span className="valueIcon">🐓</span><span>{t.v1}</span></div>
          <div className="value"><span className="valueIcon">🍃</span><span>{t.v2}</span></div>
          <div className="value"><span className="valueIcon">♥</span><span>{t.v3}</span></div>
          <div className="value"><span className="valueIcon">🇭🇳</span><span>{t.v4}</span></div>
        </section>

        <section id="story" className="middle">
          <div className="storyText">
            <div className="eyebrow">{t.storyEyebrow}</div>
            <h2>{storyTitle}</h2>
            <p>{storyBody}</p>
            <div className="signature">{t.signature}</div>
          </div>

          <img src={FAMILY} alt="Vi Pollos family" className="familyPhoto" />

          <div className="featured">
            <h3>{t.featured}</h3>
            <div className="dishRow">
              <div className="dish"><div className="dishIcon">🇭🇳</div><span>{t.d1}</span></div>
              <div className="dish"><div className="dishIcon">✦</div><span>{t.d2}</span></div>
              <div className="dish"><div className="dishIcon">♥</div><span>{t.d3}</span></div>
              <div className="dish"><div className="dishIcon">☀</div><span>{t.d4}</span></div>
            </div>
          </div>
        </section>

        <section id="visit" className="bottom">
          <div className="caterBox">
            <div className="eyebrow">{t.occasion}</div>
            <h3>{t.cateringTitle}</h3>
            <p>{t.cateringBody}</p>
            <a href={cateringHref} className="eventBtn">{t.event} →</a>
          </div>

          <div className="quoteBox">
            <div className="quoteMark">“</div>
            <p>{t.quote}</p>
            <div className="stars">★★★★★</div>
            <div className="guest">{t.guest}</div>
          </div>

          <div className="visit">
            <h3>{t.visit}</h3>
            <p>📍 {addressLine}<br/>{cityStateZip}</p>
            <p>☎ {phone}</p>
            <p style={{ whiteSpace: "pre-line" }}>◷ {hoursText}</p>
            <a
              className="mapBtn"
              href={`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(
                `${addressLine} ${cityStateZip}`
              )}`}
              target="_blank"
              rel="noreferrer"
            >
              {t.map}
            </a>
          </div>
        </section>

        <footer className="footer">{t.footer} &nbsp;&nbsp; f &nbsp;&nbsp; ◎ &nbsp;&nbsp; ♪</footer>
      </div>
    </main>
  );
}
